        # Add renewal eligibility
        cert_summary["RenewalEligibility"] = "INELIGIBLE"

        # Add validity dates
        cert_summary["NotBefore"] = cert_bundle._not_valid_before(cert)
        cert_summary["NotAfter"] = cert_bundle._not_valid_after(cert)

        certs.append(cert_summary)

    result = {"CertificateSummaryList": certs}
    return json.dumps(result)

