def list_certificates(self) -> str:
    certs = []
    statuses = self._get_param("CertificateStatuses")
    for cert_bundle in self.acm_backend.list_certificates(statuses):
        # Get certificate details
        cert = cert_bundle._cert
        cert_summary = {
            "CertificateArn": cert_bundle.arn,
            "DomainName": cert_bundle.common_name,
            "InUse": len(cert_bundle.in_use_by) > 0,
            "Status": cert_bundle.status,
            "Type": cert_bundle.type
        }

        # Add key algorithm
        if cert_bundle._key.key_size == 1024:
            cert_summary["KeyAlgorithm"] = "RSA_1024"
        elif cert_bundle._key.key_size == 2048:
            cert_summary["KeyAlgorithm"] = "RSA_2048"
        else:
            cert_summary["KeyAlgorithm"] = "EC_prime256v1"

        # Add renewal eligibility
        cert_summary["RenewalEligibility"] = "INELIGIBLE"

        # Add validity dates - use epoch timestamps for proper serialization
        from moto.acm.models import datetime_to_epoch
        cert_summary["NotBefore"] = datetime_to_epoch(cert_bundle._not_valid_before(cert))
        cert_summary["NotAfter"] = datetime_to_epoch(cert_bundle._not_valid_after(cert))

        certs.append(cert_summary)

    result = {"CertificateSummaryList": certs}
    return json.dumps(result)
